module leftist_heap
struct Node { key i64 left int right int npl int }
fn merge_nodes(mut a []Node,x0 int,y0 int) int { if x0<0{return y0};if y0<0{return x0};mut x:=x0;mut y:=y0;if a[x].key>a[y].key{t:=x;x=y;y=t};a[x].right=merge_nodes(mut a,a[x].right,y);if a[x].left<0{a[x].left=a[x].right;a[x].right= -1}else{if a[a[x].left].npl<a[a[x].right].npl{t:=a[x].left;a[x].left=a[x].right;a[x].right=t};a[x].npl=a[a[x].right].npl+1};return x }
@[export: 'leftist_heap']
pub fn leftist_heap(v &i64,n usize) f64 {if n<1||n>43{return -1e300};m:=unsafe{v[0]};if m<0||m>14||n!=usize(1+3*m){return -1e300};mut a:=[]Node{len:14};for i in 0..14{a[i].left= -1;a[i].right= -1};mut roots:=[2]int{-1,-1};mut used:=0;mut ex:=0;mut result:=i64(0);for i in 0..int(m){k:=unsafe{v[1+3*i]};h:=unsafe{v[2+3*i]};z:=unsafe{v[3+3*i]};if k<0||k>3{return -1e300};if k==0{if h<0||h>1||z<0||z>9{return -1e300};a[used]=Node{key:z,left:-1,right:-1,npl:0};hi:=int(h);roots[hi]=merge_nodes(mut a,used,roots[hi]);used++}else if k==1{if h<0||h>1||z!=0{return -1e300};ex++;if ex>10{return -1e300};hi:=int(h);r:=roots[hi];mut got:=i64(-1);if r>=0{got=a[r].key;l:=a[r].left;rr:=a[r].right;roots[hi]=merge_nodes(mut a,l,rr)};result=result*13+got+2}else if k==2{if h!=0||z!=0{return -1e300};roots[0]=merge_nodes(mut a,roots[0],roots[1]);roots[1]= -1}else{if h<0||h>1||z!=0{return -1e300};roots[int(h)]= -1}};return f64(result)}
